INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62565782', 62565782, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA TARDAMU SABU', 'Jasa Konsultansi Pengusulan Program Kegiatan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Nusa Tenggara Timur, Sabu Raijua (Kab.)', 50000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Konsultansi Pengusulan Program Kegiatan dengan Volume 1 Paket pekerjaan', '1. Latar Belakang Dibutuhkan tenaga ahli untuk menyusun dokumen usulan program kegiatan yang komprehensif, akuntabel, dan sesuai dengan standar regulasi guna mendukung pencapaian target strategis organisasi. 2. Tujuan Pekerjaan Menghasilkan dokumen usulan program yang layak secara teknis dan finansial. Menjamin kesesuaian program dengan dokumen perencanaan induk (Renstra/RPJMD). Menyediakan rincian estimasi kebutuhan sumber daya (anggaran, personil, dan waktu). 3. Ruang Lingkup Utama Analisis Situasi: Identifikasi masalah dan urgensi kegiatan melalui data lapangan/literatur. Perancangan Program: Penentuan metode pelaksanaan, sasaran (target group), dan indikator keberhasilan (Output & Outcome). Penyusunan RAB: Perhitungan biaya detail merujuk pada Standar Biaya Masukan (SBM) yang berlaku. Mitigasi Risiko: Identifikasi potensi kendala pelaksanaan dan solusinya. 4. Output / Produk Akhir Penyedia jasa wajib menyerahkan dokumen dalam bentuk cetak (hardcopy) dan digital (softcopy) berupa: Dokumen 1: Naskah Usulan Program (Latar belakang, tujuan, metodologi, dan desain teknis)/TOR dan Gambar. Buku 2: Rencana Anggaran Biaya (RAB) (Rincian komponen biaya per item). Dokumen 3: Jadwal Pelaksanaan (Kurva S) (Timeline detail pelaksanaan kegiatan).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 641940);
