INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62591622', 62591622, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS PEMADAM KEBAKARAN', 'Belanja Modal Alat Pemadam Kebakaran - Mobil Penyelamatan', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 1661554338, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Modal Alat Pemadam Kebakaran - Mobil Penyelamatan', '1. Chasis menggunakan merek Toyota atau Mitsubishi dengan tipe penggerak 4x4 dan transmisi Manual 2. Cabin kendaraan tipe Double Cabin dengan kapasitas 5 orang beserta pengemudi 3. Cabin dilindungi dengan Roll Case yang berfungsi untuk menahan benturan 4. Dilengkapi dengan Lift Kit Suspension 5. Body Penutup dan Rangka - Material Body : Menggunakan bahan Plat galvanil ketebalan minimal 1.2mm - Material rangka : Menggunakan bahan Baja profil (mild steel profile) ketebalan minimal 3mm - Material lantai : Menggunakan bahan Plat bordes alumunium ketebalan minimal 2 mm - Material deck : Menggunakan bahan Plat bordes alumunium ketebalan minimal 3 mm 6. Memiliki tangga untuk akses ke deck atas dan terdapat Railling pengaman di atas kendaaran dengan bahan dari Stainless Steel 7. Terdapat kompartemen peralatan yang terpisah di bagian samping dan belakang unit dan dilengkapi terdapat lampu penerangan 8. Pengecatan body di lapisi dengan Polyurethane Prime Coat dan di finishing dengan cat Polyurethane (PU) 9. Sistem Elektrikal menggunakan connector water proof dan dust proof (tahan air dan debu) dan dilengkapi dengan panel kontrol untuk memudahkan pengecekan dan perbaikan 10. Bumper depan menggunakan bahan kombinasi Besi plat tebal dengan pipa besi dan dilengkapi dengan Bracket Winch 11. Bumper belakang menggunakan bahan kombinasi Besi plat tebal dan besi UNP 12. Dilengkapi dengan Alat Pelindung Diri (APD) Penyelamatan dan Peratalan dan Perlengkapan Penyelamatan meliputi: - Hammer Drill - Jack Hammer - Concrete Cutter - Head Immobilizer - Shoring - Sava High Pressure Flat - Scuba Gear - Pressure Water Tank - Pompa Portable - Rescue Coverall (Pakaian Penyelamatan) - Rescue Glove ( Sarung Tangan Penyelamatan) - Helm Rescue - Safety Shoes (Sepatu Safety) - First Aid Kit (kotak P3K) - Bolt Cutter - Hammer - Baju Anti Sengatan Lebah - Kapak Besar - Linggis - Tongkat Pengait (Hook) - Tali Tambang - Tongkat Penjepit Ular 13. Terdapat peralatan Electrical (kelistrikan) meliputi: - Light bar warna Merah LED - Sirine public address system c/w microphone, speaker - Lampu strobo - Lampu sorot/lampu penerangan yang terletak diatas mobil - Radio Rig - Handy Talky - Tail light LED - Lampu loker,lampu cabin dan ruang pompa - Senter - Toa Megaphone 14. Terdapat perlengkapan standard meliputi: - Segitiga pengaman - Tool kit set - Dongkrak - Kotak P3K - Ban serep 15. Menyediakan Training After Sales yang meliputi: - Disediakan pelatihan (Training) untuk pengoperasian dan perawatan - Garansi Chasis utama kendaraan - Garansi Karoseri kendaraan minimal 1 tahun - Garansi peralatan elektrik minimal 1 tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 643673);
