INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62593013', 62593013, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI PADANG 01', 'Pengadaan tenaga satpam', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Barat, Padang (Kota)', 399568000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '104 orang/bulan', 'Menyelenggarakan keamanan dan ketertiban dilingkungan Pengadilan Negeri Padang', '1.Menyelenggarakan keamanan dan ketertiban dilingkungan/kawasan kerja khususnya pengamanan phisik. 2.Mencegah dan mengatasi timbulnya ancaman dan gangguan lingkungan serta ketertiban pelanggaran hukum dilingkungan pengguna jasa secara phisik melalui kegiatan pengaturan, penjagaan, pengawalan dan patroli. 3.Melakukan pengaturan dengan maksud menegakkan tata tertib yang berlaku dilingkungan kerja perusahaan khususnya menyangkut keamanan dan ketertiban yang diberikan oleh SECURITY MANAGEMENT: Pengaturan pemakaian ID Card sesuai dengan aturan. Pengaturan terhadap tamu. Pengaturan parkir dan dilarang memungut uang parkir. 4.Melakukan penjagaan yang dimaksud mengawasi masuk/keluarnya orang maupun barang serta mengawasi keadaan ataupun hal-hal yang mencurigakan disekitar tempat tugas jaga dan dilakukan pengawasan ekstra didaerah pintu darurat disetiap lantai gedung. 5.Melakukan patroli sekitar kawasan kerja menurut route dan waktu tertentu dengan maksud mangadakan penelitian dan pemeriksaan terhadap segala sesuatu yang tidak wajar. 6.Menyerap informasi dari segala sumber yang berkaitan dengan adanya dugaan yang dapat menyebabkan tindakan kriminal atau provokasi yang dapat merugikan perusahaan.ditugaskan agar malapor kepada security management. 7.Bersikap jujur, berani, bijaksana dan tanggap terhadap segala situasi serta mampu bertindak tegas dalam memberikan pengamanan ataupun perlindungan dikawasan kerja dengan tetap menjunjung tinggi hak asasi manusia dan azas praduga tak bersalah. 8.Mentaati peraturan perusahaan dan menghormati norma-norma yang berlaku dilingkungan perusahaan maupun dilingkungan masyarakat sekitarnya. 9.Setiap anggota security wajib menjalankan tugas dengan penuh rasa tanggung jawab dan berdedikasi yang tinggi terhadap setiaр pelanggaran akan dikenakan sanksi. 10.Memberikan tanda-tanda bahaya pada saat kejadian darurat (kebakaran, bencana banjir, gempa, dll) dan wajib memberikan pertolongan dan bantuan evakuasi penyelamatan dikawasan kerja. 11.Melakukan pelayanan sesuai dengan standar layanan Pengadilan Negeri Padang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 644175);
