INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568266', 62568266, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Koneksi internet', 'Barang', 'Dikecualikan', 'Kalimantan Timur, Kutai Barat (Kab.)', 26359000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1 THN, @Rp 26.359.000)', '1. Koneksi internet ( 1 THN, @Rp 26.359.000);', 'Nama Paket : Koneksi Internet Volume : 1 THN (Tahun) Harga Satuan : @ Rp26.359.000 1. Ruang Lingkup Pekerjaan Penyedia menyediakan layanan koneksi internet untuk mendukung kegiatan operasional dan pelayanan data di lingkungan kantor selama periode 1 (satu) tahun. 2. Spesifikasi Teknis 1. Layanan internet bersifat dedicated/broadband yang stabil untuk kebutuhan operasional perkantoran. 2. Kecepatan akses internet disesuaikan dengan kebutuhan operasional kantor dan mendukung aktivitas seperti pengiriman data, komunikasi daring, serta akses aplikasi berbasis web. 3. Layanan tersedia selama 24 (dua puluh empat) jam setiap hari selama masa kontrak. 4. Penyedia menyediakan perangkat pendukung yang diperlukan untuk koneksi internet (misalnya modem/router) apabila dibutuhkan. 5. Penyedia memberikan dukungan teknis dan layanan perbaikan apabila terjadi gangguan koneksi selama masa layanan. 3. Persyaratan 1. Penyedia merupakan perusahaan penyedia layanan internet yang memiliki izin usaha yang sah. 2. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 3. Harga sudah termasuk pajak, biaya instalasi, dan biaya layanan selama masa kontrak. 4. Penyedia bertanggung jawab atas stabilitas layanan serta penanganan gangguan teknis selama periode layanan. 5. Apabila terjadi gangguan layanan yang berkepanjangan, penyedia wajib melakukan perbaikan atau penyesuaian layanan sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 645909);
