INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62565924', 62565924, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Pengembangan Aplikasi Manajemen Pemerintahan VI Tahap 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 71685000, 'December 2025', 'APBD', 1, 1, '6 OB', 'membuat desain proses bisnis, mendesain kembali workflow agar menjadi lebih efisien dan memperhatikan kebutuhan integasi dengan aplikasi lainnya - mempresentasikan desain proses bisnis yang sudah selesai kepada expert user/narasumber - membuat desain yang diperlukan untuk pemrograman (penulisan source code program) seperti : desain database (database, tabel, relasi, normalisasi, dan tata nama), screen layout (interface/antarmuka), diagram proses (algoritma dan logika program) dan layout report (list, detail report, dan summary report) - membangun core framework dan plugin jquery yang dibutuhkan - membuat model, view dan controller aplikasi berdasarkan rancang bangun sistem - mengembangkan Aplikasi baru maupun penambahan fitur – fitur baru di aplikasi eksisting, seperti : Aplikasi Tangerang Gorvu, PPDB, dan lain lain - mengembangkan aplikasi berbasis mobile baru maupun penambahan fitur di aplikasi eksisting, seperti : Tangerang Live, Sidata dan lain lain - test execution, melakukan tahap pelaksanaan testing terhadap semua skenario yang telah dibuat di test planning', 'Administrator Web Tingkat II, Pemrogram Perangkat Lunak (Programmer), yaitu S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika dengan kualifikasi: - Pria/Wanita usia maksimal 40 tahun; - Pendidikan S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika; - Memiliki pengalaman kerja lebih dari 3 (tiga) tahun di bidang Teknik Informasi; - Memahami konsep pemrograman berbasiskan obyek (OOP); - Memahami android studio, java native, http request (volley, retrofit); - Menguasai konsep webservices/ web API (REST API); - Terbiasa menggunakan 3rd party libraries; atau - Terbiasa menggunakan framework Code Igniter (CI); - Menguasai bootstrap, html, css, javascript, SQL, PostGreSQL, SQL Server atau Oracle; - Menguasai konsep web service/ webAPI, XML-RPC, SOAP, REST, RESTful; - Dapat mengoperasikan Komputer; - Menguasai aplikasi perkantoran (ms office atau sejenis); - Memiliki Perangkat Kerja dengan platform Android; - Diutamakan memiliki Sertifikat Nasional (BNSP) bidang keahlian Pemrograman; - Bersedia bekerja di lokasi Dinas Komunikasi dan Informatika selama kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 647490);
