INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62591266', 62591266, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'UPT Puskesmas Mantrijeron', 'BELANJA JASA AUDIT KAP (KANTOR AKUNTAN PUBLIK) EKSTERNAL', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 20000000, 'January 2026', 'BLUD', 1, 1, '1 keg', 'Jasa audit eksternal atas laporan keuangan BLUD Puskesmas tahun berjalan untuk memberikan opini independen atas kewajaran penyajian laporan keuangan serta evaluasi sistem pengendalian internal.', '1. Penyedia jasa yang memiliki kualifikasi dan memenuhi syarat-syarat : a. Berbentuk Kantor Akuntan Publik yang terdaftar dan memiliki izin resmi dari Kementrian Keuangan Republik Indonesia b. Terdaftar sebagai anggota IAPI c. Memiliki pengalaman melaksanakan audit laporan keuangan pada instansi pemerintah, BLUD dalam kurun waktu 3 tahun terakhir d. Tidak sedang dikenakan sanksi administratif atau pembekuan izin oleh otoritas yang berwenang e. Menyediakan tim audit yang kompetent dan independen 2. Persyaratan personel (Tim audit) : a. Partner Audit i. Memiliki izin akuntan publik yang masih berlaku ii. Berpengalaman sebagai penanggung jawab audit b. Ketua Tim i. Berpengalaman dalam audit laporan keuangan instansi pemerintah dan BLUD ii. Memahami SAP/SAK dan regulasi sektor publik c. Anggota i. Memiliki latar belakang pendidikan akuntansi/keuangan ii. Berpengalaman dalam pengujian substantif dan pengendalian internal 3. Standar dan Metodologi Audit Pelaksanaan audit harus mengacu pada : a. Standar Audit (SA) yang ditetapkan oleh IAPI b. Kode etik profesi akuntan publik c. Prinsip independensi, objektivitas dan profesionalisme d. Pendekatan audit berbasis risiko (risk-based audit) 4. Output Penyedia wajib menyediakan : a. Laporan auditor independen atas laporan keuangan b. Manjemen letter yang berisi : i. Temuan audit ii. Analisis risiko iii. Rekomendasi perbaikan c. BAST pekerjaan 5. Waktu pelaksanaan audit : maksimal 30 (tiga puluh) hari kalender sejak SPMK diterbitkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 648217);
