INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62566394', 62566394, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Pengembangan Sistem Informasi Geospasial Tahap 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 67032000, 'December 2025', 'APBD', 1, 1, '4 OB', 'Merancang dan mengembangkan aplikasi geospasial berbasis web, desktop, atau mobile. Mengembangkan sistem Web Server untuk pengelolaan dan penyajian data spasial. Mengintegrasikan data geospasial dari berbagai sumber (database spasial, API, citra satelit, sensor, dan layanan peta). Mengelola dan mengoptimalkan basis data spasial (misalnya PostGIS, Spatialite, atau sejenisnya). Mengimplementasikan fungsi analisis spasial dan geoprocessing dalam aplikasi. Mengembangkan dan memelihara API dan layanan peta (WMS, WFS, WMTS, REST). Melakukan debugging, pengujian, dan peningkatan performa aplikasi geospasial. Menyusun dokumentasi teknis aplikasi dan kode program. Berkolaborasi dengan Tenaga Ahli Geospasial, analis data, dan tim pengembang lainnya. Menjaga keamanan data dan sistem geospasial sesuai standar yang berlaku.', 'Ahli Non SKA/SKK S1 Pengalaman 3 Tahun, Pemrogram Perangkat Lunak (Programmer), yaitu S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika dengan kualifikasi: - Pria/Wanita usia maksimal 40 tahun; - Pendidikan S1 Teknologi Informasi/Sistem Informasi/Informatika/Manajemen Informatika; - Memiliki pengalaman kerja lebih dari 3 (tiga) tahun di bidang Teknik Informasi; - Memahami konsep pemrograman berbasiskan obyek (OOP); - Memahami android studio, java native, http request (volley, retrofit); - Menguasai konsep webservices/ web API (REST API); - Terbiasa menggunakan 3rd party libraries; atau - Terbiasa menggunakan framework Code Igniter (CI); - Menguasai bootstrap, html, css, javascript, SQL, PostGreSQL, SQL Server atau Oracle; - Menguasai konsep web service/ webAPI, XML-RPC, SOAP, REST, RESTful; - Dapat mengoperasikan Komputer; - Menguasai aplikasi perkantoran (ms office atau sejenis); - Memiliki Perangkat Kerja dengan platform Android; - Diutamakan memiliki Sertifikat Nasional (BNSP) bidang keahlian Pemrograman; - Bersedia bekerja di lokasi Dinas Komunikasi dan Informatika selama kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 648430);
