INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568280', 62568280, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Pemeliharaan PC/laptop/notebook', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 9630000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 29, U/THN, @Rp 332.069)', '1. Pemeliharaan PC/laptop/notebook ( 29, U/THN, @Rp 332.069);', 'Nama Paket : Pemeliharaan PC/Laptop/Notebook Volume : 29 Unit/Tahun Harga Satuan : @ Rp332.069 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pemeliharaan rutin dan perbaikan ringan terhadap seluruh PC, laptop, dan notebook yang digunakan di lingkungan kantor selama periode 1 (satu) tahun agar perangkat tetap berfungsi optimal dan aman digunakan. ________________________________________ 2. Spesifikasi Teknis 1. Pemeliharaan mencakup: o Pembersihan hardware (keyboard, layar, ventilasi, dan komponen internal). o Instalasi dan pembaruan perangkat lunak dasar (operating system dan driver). o Pemeriksaan sistem kelistrikan dan konektivitas perangkat. o Perbaikan ringan akibat pemakaian normal. 2. Pemeliharaan dilakukan secara berkala sesuai jadwal atau kebutuhan teknis. 3. Penggantian komponen minor (misal: kipas, RAM tambahan, kabel, atau baterai cadangan) menggunakan suku cadang asli atau setara yang memenuhi standar pabrikan. 4. Setiap kegiatan pemeliharaan dicatat dalam buku servis atau laporan resmi. ________________________________________ 3. Persyaratan 1. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 2. Harga sudah termasuk biaya jasa, suku cadang, dan pajak. 3. Penyedia bertanggung jawab atas kelancaran, kualitas, dan keamanan pemeliharaan perangkat. 4. Apabila pemeliharaan tidak dilakukan sesuai ketentuan atau menimbulkan kerusakan baru, penyedia wajib melakukan perbaikan atau penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 648801);
