INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568273', 62568273, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Biaya langganan listrik', 'Barang', 'Dikecualikan', 'Kalimantan Timur, Kutai Barat (Kab.)', 60000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1 THN, @Rp 60.000.000 )', '1. Biaya langganan listrik ( 1 THN, @Rp 60.000.000 );', 'Nama Paket : Biaya Langganan Listrik Volume : 1 THN (Tahun) Harga Satuan : @ Rp60.000.000 1. Ruang Lingkup Pekerjaan Pembayaran biaya langganan listrik untuk mendukung operasional kegiatan perkantoran selama periode 1 (satu) tahun. 2. Spesifikasi Teknis 1. Layanan listrik digunakan untuk mendukung operasional kantor, termasuk penggunaan perangkat komputer, pencahayaan, pendingin ruangan, serta peralatan elektronik lainnya. 2. Pembayaran dilakukan sesuai dengan tagihan pemakaian listrik yang diterbitkan oleh penyedia layanan listrik. 3. Pasokan listrik tersedia selama 24 (dua puluh empat) jam untuk menunjang kegiatan operasional kantor. 4. Daya listrik yang digunakan disesuaikan dengan kapasitas daya yang terpasang pada kantor. 5. 3. Persyaratan 1. Pembayaran dilakukan sesuai dengan tagihan resmi dari penyedia layanan listrik. 2. Harga yang tercantum merupakan estimasi biaya langganan listrik selama periode 1 (satu) tahun. 3. Biaya sudah termasuk pajak dan komponen lain yang tercantum dalam tagihan listrik. 4. Bukti pembayaran/tagihan disimpan sebagai dasar pertanggungjawaban administrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 648831);
