INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568278', 62568278, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Pemeliharaan Air conditioner/AC', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 7067000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 15, U/THN, @Rp 471.134)', '1. Pemeliharaan Air conditioner/AC ( 15, U/THN, @Rp 471.134);', 'Nama Paket : Pemeliharaan Air Conditioner (AC) Volume : 15 Unit/Tahun Harga Satuan : @ Rp471.134 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pemeliharaan rutin dan perbaikan ringan pada seluruh unit AC di kantor selama periode 1 (satu) tahun agar berfungsi optimal, efisien, dan aman digunakan. ________________________________________ 2. Spesifikasi Teknis 1. Pemeliharaan mencakup: o Pembersihan filter udara, sirip evaporator, dan kondensor. o Pemeriksaan dan pengisian ulang refrigerant jika diperlukan. o Pengecekan kelistrikan dan komponen AC (kompresor, kipas, thermostat). o Perbaikan ringan akibat pemakaian normal. 2. Pemeliharaan dilakukan sesuai jadwal rutin atau sesuai kebutuhan teknis AC. 3. Penyedia menggunakan suku cadang asli atau setara yang memenuhi standar pabrikan. 4. Setiap kegiatan pemeliharaan dicatat dalam buku servis atau laporan resmi. ________________________________________ 3. Persyaratan 1. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 2. Harga sudah termasuk biaya jasa, suku cadang, dan pajak. 3. Penyedia bertanggung jawab atas kelancaran, kualitas, dan keamanan pemeliharaan AC. 4. Apabila pemeliharaan tidak dilakukan sesuai ketentuan atau menimbulkan kerusakan baru, penyedia wajib melakukan perbaikan tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 648845);
