INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568279', 62568279, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Pemeliharaan kendaraan operasional eselon iii/Operasional', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 62225000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 2 U/THN, @Rp 31.112.500)', '1. Pemeliharaan kendaraan operasional eselon iii/Operasional ( 2 U/THN, @Rp 31.112.500);', 'Nama Paket : Pemeliharaan Kendaraan Operasional Eselon III / Operasional Volume : 2 Unit/Tahun Harga Satuan : @ Rp31.112.500 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pemeliharaan kendaraan operasional Eselon III selama periode 1 (satu) tahun, meliputi perawatan rutin, servis berkala, dan perbaikan ringan agar kendaraan tetap layak pakai, aman, dan nyaman digunakan. ________________________________________ 2. Spesifikasi Teknis 1. Pemeliharaan meliputi: o Servis rutin sesuai ketentuan pabrik (ganti oli, filter, pemeriksaan rem, aki, ban, dan sistem kelistrikan). o Perbaikan ringan akibat pemakaian normal. o Pembersihan kendaraan secara berkala. 2. Penggunaan suku cadang asli atau setara yang memenuhi standar pabrikan. 3. Pemeliharaan dilakukan sesuai jadwal servis yang direkomendasikan pabrikan kendaraan. 4. Semua kegiatan pemeliharaan dicatat dalam buku servis atau laporan resmi. ________________________________________ 3. Persyaratan 1. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 2. Harga sudah termasuk biaya jasa, suku cadang, dan pajak. 3. Penyedia bertanggung jawab atas kelancaran, kualitas, dan keamanan pemeliharaan kendaraan. 4. Apabila pemeliharaan tidak dilakukan sesuai ketentuan atau menimbulkan kerusakan baru, penyedia wajib melakukan perbaikan tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 649115);
