INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62568274', 62568274, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Biaya langganan air', 'Barang', 'Dikecualikan', 'Kalimantan Timur, Kutai Barat (Kab.)', 6792000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 THN, @Rp 6.792.000 )', '1. Biaya langganan air ( 1 THN, @Rp 6.792.000 );', 'Nama Paket : Biaya Langganan Air Volume : 1 THN (Tahun) Harga Satuan : @ Rp6.792.000 ________________________________________ 1. Ruang Lingkup Pekerjaan Pembayaran biaya langganan air untuk mendukung operasional kegiatan perkantoran selama periode 1 (satu) tahun, termasuk kebutuhan kebersihan. ________________________________________ 2. Spesifikasi Teknis 1. Layanan air digunakan untuk mendukung kebutuhan operasional kantor, seperti penggunaan untuk toilet, wastafel, kebersihan ruangan 2. Pembayaran dilakukan sesuai tagihan resmi dari penyedia layanan air. 3. Air tersedia secara terus-menerus selama jam operasional kantor. 4. Kapasitas pasokan air disesuaikan dengan kebutuhan kantor sesuai jumlah pegawai dan luas ruangan. ________________________________________ 3. Persyaratan 1. Pembayaran dilakukan sesuai tagihan resmi dari penyedia layanan air. 2. Harga yang tercantum merupakan estimasi biaya langganan air selama periode 1 (satu) tahun. 3. Harga sudah termasuk pajak dan komponen lain yang tercantum dalam tagihan. 4. Bukti pembayaran/tagihan disimpan sebagai dasar pertanggungjawaban administrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 649931);
